#include "nonlinear_solver.hpp"
int main(int argc,char**argv){try{fs::path out=argc>1?argv[1]:"nonlinear_results";bool polish=argc>2&&std::string(argv[2])=="polish";fs::create_directories(out);std::ofstream csv(out/"results.csv"),audit(out/"schur_identity.csv");csv<<std::setprecision(16)<<"N,stiffness,mass_ratio,h,method,converged,primal,stationarity,full_stationarity,evaluations,ms,curvature,raw_component_total,full_max_balance,reason\n";audit<<std::setprecision(16)<<"N,stiffness,mass_ratio,h,relative_position_step_error,relative_work_step_error,pass\n";
 for(int N:{8,32})for(double k:{1.,10.})for(double mass:{1.,10.})for(double h:{1./60,1./30}){auto c=chain_case(N,k,mass);double E=std::max(1e-6,energy(c.model,c.initial)-minimum_energy(c.model));LiftedFull f(c.model,c.initial,h,E);ScaledReduced p(f,1);Solve initial;initial.z=p.initial();initial.dual=V::Zero(1);V dual=p.full_dual(initial),df=newton_step(f.evaluate(f.initial()),dual),dr=newton_step(p.evaluate(initial.z),initial.dual);auto data=p.data(initial.z);double qe=(df.head(p.p.n)-dr.head(p.p.n)).norm()/std::max(1.,dr.head(p.p.n).norm()),we=(df.segment(p.p.n,f.p.wcount)-p.P*data.G*dr.head(p.p.n)).norm()/std::max(1.,df.segment(p.p.n,f.p.wcount).norm());audit<<N<<','<<k<<','<<mass<<','<<h<<','<<qe<<','<<we<<','<<(qe<1e-7&&we<1e-7)<<'\n';audit.flush();
 for(std::string method:polish?std::vector<std::string>{"reduced_GN_then_Newton"}:std::vector<std::string>{"full_zero_dual","full_aligned_dual","reduced_exact","reduced_GN","reduced_exact_scaled","reduced_GN_scaled"}){Solve s;double fullstat,curv=0,rawtotal=0,fullbalance=0;if(method.rfind("full_",0)==0){s=solve(f,128,[](const V&,const Evaluation&e){return e.objective.H;},method=="full_aligned_dual"?&dual:nullptr);fullstat=s.dual_residual;V rr=residuals(f.evaluate(s.z));rawtotal=std::abs(rr.sum());fullbalance=rr.lpNorm<Eigen::Infinity>();if(s.converged)curv=reduced_curvature(f,s);}else{ScaledReduced r(f,method.find("scaled")!=std::string::npos?std::sqrt(p.B.rows()):1);bool gn=method.find("GN")!=std::string::npos;s=solve(r,polish?64:128,[&](const V&q,const Evaluation&e){return gn?r.gauss_newton(q,e):e.objective.H;});if(polish&&!s.converged){auto first=s;s=solve(r,128-first.evaluations,[](const V&,const Evaluation&e){return e.objective.H;},&first.dual,&first.z);s.evaluations+=first.evaluations;s.milliseconds+=first.milliseconds;}auto reconstructed=f.evaluate(r.expand(s.z));fullstat=stationarity(reconstructed,r.full_dual_scaled(s));V rr=residuals(reconstructed);rawtotal=std::abs(rr.sum());fullbalance=rr.lpNorm<Eigen::Infinity>();if(s.converged)curv=reduced_curvature(r,s);}
 csv<<N<<','<<k<<','<<mass<<','<<h<<','<<method<<','<<s.converged<<','<<s.primal<<','<<s.dual_residual<<','<<fullstat<<','<<s.evaluations<<','<<s.milliseconds<<','<<curv<<','<<rawtotal<<','<<fullbalance<<','<<s.reason<<'\n';csv.flush();std::cout<<N<<' '<<k<<' '<<mass<<' '<<h<<' '<<method<<' '<<s.converged<<std::endl;}
 }return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
